1	/* Low-level file I/O helpers shared by every format module.
2	 *
3	 * Original work; the behaviour reproduced here (in particular the wording of
4	 * the "overriding ..." diagnostics) was determined by running the reference
5	 * program.  See ../notes/formats_i.md.
6	 *
7	 * All multi-byte accessors honour ft->encoding.reverse_bytes, which is
8	 * SOX_OPTION_YES when the on-disk byte order is the opposite of the host's.
9	 * The host this is built for is little-endian, but the code below only ever
10	 * reverses bytes relative to the host, so it stays correct either way.
11	 */
12	#include "sox_i.h"
13	#include <inttypes.h>
14	#include <stdarg.h>
15	#include <sys/types.h>
16	#include <sys/stat.h>
17	#include <unistd.h>
18	
19	#define reversing(ft) ((ft)->encoding.reverse_bytes == SOX_OPTION_YES)
20	
21	/*-------------------------------- utilities --------------------------------*/
22	
23	static int io_fail(sox_format_t ft, int err, char const *fmt, ...)
24	{
25	  va_list ap;
26	  va_start(ap, fmt);
27	  vsnprintf(ft->sox_errstr, sizeof(ft->sox_errstr), fmt, ap);
28	  va_end(ap);
29	  ft->sox_errno = err;
30	  return SOX_EOF;
31	}
32	
33	/* Reverse the bytes of each of `n' items of `size' bytes, in place. */
34	static void reverse_items(void *p, size_t size, size_t n)
35	{
36	  unsigned char *q = p;
37	  size_t i, j, half = size / 2;
38	
39	  for (i = 0; i < n; ++i, q += size)
40	    for (j = 0; j < half; ++j) {
41	      unsigned char t = q[j];
42	      q[j] = q[size - 1 - j];
43	      q[size - 1 - j] = t;
44	    }
45	}
46	
47	static uint32_t swap32(uint32_t x)
48	{
49	  return ((x & 0x000000ffu) << 24) | ((x & 0x0000ff00u) <<  8) |
50	         ((x & 0x00ff0000u) >>  8) | ((x & 0xff000000u) >> 24);
51	}
52	
53	static uint64_t swap64(uint64_t x)
54	{
55	  return ((uint64_t)swap32((uint32_t)x) << 32) | swap32((uint32_t)(x >> 32));
56	}
