58	/*---------------------------- raw buffered i/o -----------------------------*/
59	
60	size_t lsx_readbuf(sox_format_t ft, void *buf, size_t len)
61	{
62	  size_t got;
63	
64	  if (!ft->fp || !len)
65	    return 0;
66	  got = fread(buf, (size_t)1, len, ft->fp);
67	  ft->tell_off += (off_t)got;
68	  ft->tell_off_valid = sox_true;
69	  if (got != len) {
70	    ft->eof = sox_true;
71	    if (ferror(ft->fp))
72	      io_fail(ft, errno, "error reading `%s': %s",
73	              ft->filename ? ft->filename : "", strerror(errno));
74	  }
75	  return got;
76	}
77	
78	size_t lsx_writebuf(sox_format_t ft, void const *buf, size_t len)
79	{
80	  size_t put;
81	
82	  if (!ft->fp || !len)
83	    return 0;
84	  put = fwrite(buf, (size_t)1, len, ft->fp);
85	  ft->tell_off += (off_t)put;
86	  ft->tell_off_valid = sox_true;
87	  if (put != len) {
88	    ft->eof = sox_true;
89	    io_fail(ft, errno, "error writing `%s': %s",
90	            ft->filename ? ft->filename : "", strerror(errno));
91	  }
92	  return put;
93	}
