128	off_t lsx_tell(sox_format_t ft)
129	{
130	  if (ft->fp && ft->seekable) {
131	    off_t where = ftello(ft->fp);
132	    if (where >= 0)
133	      return where;
134	  }
135	  return ft->tell_off;
136	}
137	
138	int lsx_unreadb(sox_format_t ft, unsigned b)
139	{
140	  if (!ft->fp || ungetc((int)(b & 0xff), ft->fp) == EOF)
141	    return SOX_EOF;
142	  ft->tell_off -= 1;
143	  ft->eof = sox_false;
144	  return SOX_SUCCESS;
145	}
146	
147	/* Consume and throw away `n' bytes; used when a stream cannot be seeked. */
148	static int discard_bytes(sox_format_t ft, uint64_t n)
149	{
150	  char trash[1024];
151	
152	  while (n) {
153	    size_t want = n > sizeof(trash) ? sizeof(trash) : (size_t)n;
154	    size_t got = lsx_readbuf(ft, trash, want);
155	    if (!got)
156	      return SOX_EOF;
157	    n -= got;
158	  }
159	  return SOX_SUCCESS;
160	}
161	
162	int lsx_seeki(sox_format_t ft, off_t offset, int whence)
163	{
164	  if (!ft->fp)
165	    return io_fail(ft, SOX_EOF, "no file to seek in");
166	
167	  if (!ft->seekable) {
168	    /* Seeking forwards in a stream can be emulated by reading. */
169	    if (whence == SEEK_CUR && offset >= 0) {
170	      if (discard_bytes(ft, (uint64_t)offset) != SOX_SUCCESS)
171	        return io_fail(ft, SOX_EOF, "`%s': offset past EOF",
172	                       ft->filename ? ft->filename : "");
173	      ft->sox_errno = SOX_SUCCESS;
174	      return SOX_SUCCESS;
175	    }
176	    return io_fail(ft, SOX_EOF, "`%s': file is not seekable",
177	                   ft->filename ? ft->filename : "");
178	  }
179	
180	  if (fseeko(ft->fp, offset, whence) < 0)
181	    return io_fail(ft, errno, "`%s': %s", ft->filename ? ft->filename : "",
182	                   strerror(errno));
183	
184	  ft->tell_off = ftello(ft->fp);
185	  ft->tell_off_valid = sox_true;
186	  ft->eof = sox_false;
187	  ft->sox_errno = SOX_SUCCESS;
188	  return SOX_SUCCESS;
189	}
190	
191	int lsx_skipbytes(sox_format_t ft, size_t n)
192	{
193	  if (!n)
194	    return SOX_SUCCESS;
195	  if (ft->seekable && ft->fp && fseeko(ft->fp, (off_t)n, SEEK_CUR) >= 0) {
196	    ft->tell_off = ftello(ft->fp);
197	    ft->tell_off_valid = sox_true;
198	    return SOX_SUCCESS;
199	  }
200	  return discard_bytes(ft, (uint64_t)n);
201	}
202	
203	int lsx_padbytes(sox_format_t ft, size_t n)
204	{
205	  static char const zeros[1024];
206	
207	  while (n) {
208	    size_t want = n > sizeof(zeros) ? sizeof(zeros) : n;
209	    if (lsx_writebuf(ft, zeros, want) != want)
210	      return SOX_EOF;
211	    n -= want;
212	  }
213	  return SOX_SUCCESS;
214	}
215	
216	uint64_t lsx_filelength(sox_format_t ft)
217	{
218	  struct stat st;
219	
220	  if (!ft->fp)
221	    return 0;
222	  if (ft->mode == 'w')
223	    fflush(ft->fp);
224	  if (fstat(fileno(ft->fp), &st) < 0 || !S_ISREG(st.st_mode))
225	    return 0;
226	  return (uint64_t)st.st_size;
227	}
