242	int lsx_readw(sox_format_t ft, uint16_t *uw)
243	{
244	  unsigned char b[2];
245	
246	  if (lsx_readbuf(ft, b, (size_t)2) != 2)
247	    return SOX_EOF;
248	  *uw = reversing(ft) ? (uint16_t)(((uint16_t)b[0] << 8) | b[1])
249	                      : (uint16_t)(((uint16_t)b[1] << 8) | b[0]);
250	  return SOX_SUCCESS;
251	}
252	
253	int lsx_writew(sox_format_t ft, unsigned uw)
254	{
255	  unsigned char b[2];
256	
257	  if (reversing(ft)) {
258	    b[0] = (unsigned char)(uw >> 8);
259	    b[1] = (unsigned char)uw;
260	  } else {
261	    b[0] = (unsigned char)uw;
262	    b[1] = (unsigned char)(uw >> 8);
263	  }
264	  return lsx_writebuf(ft, b, (size_t)2) == 2 ? SOX_SUCCESS : SOX_EOF;
265	}
266	
267	int lsx_read3(sox_format_t ft, uint32_t *u3)
268	{
269	  unsigned char b[3];
270	
271	  if (lsx_readbuf(ft, b, (size_t)3) != 3)
272	    return SOX_EOF;
273	  *u3 = reversing(ft)
274	      ? ((uint32_t)b[0] << 16) | ((uint32_t)b[1] << 8) | b[2]
275	      : ((uint32_t)b[2] << 16) | ((uint32_t)b[1] << 8) | b[0];
276	  return SOX_SUCCESS;
277	}
278	
279	int lsx_write3(sox_format_t ft, uint32_t u3)
280	{
281	  unsigned char b[3];
282	
283	  if (reversing(ft)) {
284	    b[0] = (unsigned char)(u3 >> 16);
285	    b[1] = (unsigned char)(u3 >> 8);
286	    b[2] = (unsigned char)u3;
287	  } else {
288	    b[0] = (unsigned char)u3;
289	    b[1] = (unsigned char)(u3 >> 8);
290	    b[2] = (unsigned char)(u3 >> 16);
291	  }
292	  return lsx_writebuf(ft, b, (size_t)3) == 3 ? SOX_SUCCESS : SOX_EOF;
293	}
