364	/*--------------------------------- strings ---------------------------------*/
365	
366	/* Read at most `len' characters, stopping early at a NUL or a newline (which
367	 * is consumed but not stored).  A terminating NUL is always appended, so the
368	 * buffer must have room for len + 1 characters.  SOX_EOF is returned if the
369	 * file ended before a terminator was seen; whatever was read is still
370	 * NUL-terminated. */
371	int lsx_reads(sox_format_t ft, char *c, size_t len)
372	{
373	  size_t n = 0;
374	  int result = SOX_SUCCESS;
375	
376	  while (n < len) {
377	    unsigned char in;
378	    if (lsx_readbuf(ft, &in, (size_t)1) != 1) {
379	      result = SOX_EOF;
380	      break;
381	    }
382	    if (in == '\0' || in == '\n')
383	      break;
384	    c[n++] = (char)in;
385	  }
386	  c[n] = '\0';
387	  return result;
388	}
389	
390	/* Write the string, excluding its terminating NUL. */
391	int lsx_writes(sox_format_t ft, char const *c)
392	{
393	  size_t len = strlen(c);
394	  return lsx_writebuf(ft, c, len) == len ? SOX_SUCCESS : SOX_EOF;
395	}
396	
397	/* Read exactly `len' bytes; no NUL is appended. */
398	int lsx_readchars(sox_format_t ft, char *chars, size_t len)
399	{
400	  return lsx_readbuf(ft, chars, len) == len ? SOX_SUCCESS : SOX_EOF;
401	}
