403	/*------------------------------ array accessors ----------------------------*/
404	
405	static size_t read_items(sox_format_t ft, void *buf, size_t size, size_t len)
406	{
407	  size_t got = lsx_readbuf(ft, buf, len * size) / size;
408	
409	  if (got && reversing(ft))
410	    reverse_items(buf, size, got);
411	  return got;
412	}
413	
414	static size_t write_items(sox_format_t ft, void const *buf, size_t size,
415	                          size_t len)
416	{
417	  char tmp[4096];
418	  size_t per = sizeof(tmp) / size, done = 0;
419	  char const *p = buf;
420	
421	  if (!reversing(ft))
422	    return lsx_writebuf(ft, buf, len * size) / size;
423	
424	  while (done < len) {
425	    size_t want = len - done < per ? len - done : per;
426	    size_t put;
427	    memcpy(tmp, p + done * size, want * size);
428	    reverse_items(tmp, size, want);
429	    put = lsx_writebuf(ft, tmp, want * size) / size;
430	    done += put;
431	    if (put != want)
432	      break;
433	  }
434	  return done;
435	}
436	
437	size_t lsx_read_b_buf(sox_format_t ft, uint8_t *buf, size_t len)
438	{
439	  return lsx_readbuf(ft, buf, len);
440	}
441	
442	size_t lsx_write_b_buf(sox_format_t ft, uint8_t const *buf, size_t len)
443	{
444	  return lsx_writebuf(ft, buf, len);
445	}
