447	size_t lsx_read_w_buf(sox_format_t ft, uint16_t *buf, size_t len)
448	{
449	  return read_items(ft, buf, sizeof(*buf), len);
450	}
451	
452	size_t lsx_write_w_buf(sox_format_t ft, uint16_t const *buf, size_t len)
453	{
454	  return write_items(ft, buf, sizeof(*buf), len);
455	}
456	
457	size_t lsx_read_3_buf(sox_format_t ft, uint32_t *buf, size_t len)
458	{
459	  unsigned char tmp[3 * 512];
460	  size_t per = sizeof(tmp) / 3, done = 0;
461	
462	  while (done < len) {
463	    size_t want = len - done < per ? len - done : per;
464	    size_t got = lsx_readbuf(ft, tmp, want * 3) / 3, i;
465	    for (i = 0; i < got; ++i) {
466	      unsigned char *b = tmp + i * 3;
467	      buf[done + i] = reversing(ft)
468	          ? ((uint32_t)b[0] << 16) | ((uint32_t)b[1] << 8) | b[2]
469	          : ((uint32_t)b[2] << 16) | ((uint32_t)b[1] << 8) | b[0];
470	    }
471	    done += got;
472	    if (got != want)
473	      break;
474	  }
475	  return done;
476	}
477	
478	size_t lsx_write_3_buf(sox_format_t ft, uint32_t const *buf, size_t len)
479	{
480	  unsigned char tmp[3 * 512];
481	  size_t per = sizeof(tmp) / 3, done = 0;
482	
483	  while (done < len) {
484	    size_t want = len - done < per ? len - done : per, put, i;
485	    for (i = 0; i < want; ++i) {
486	      unsigned char *b = tmp + i * 3;
487	      uint32_t v = buf[done + i];
488	      if (reversing(ft)) {
489	        b[0] = (unsigned char)(v >> 16);
490	        b[1] = (unsigned char)(v >> 8);
491	        b[2] = (unsigned char)v;
492	      } else {
493	        b[0] = (unsigned char)v;
494	        b[1] = (unsigned char)(v >> 8);
495	        b[2] = (unsigned char)(v >> 16);
496	      }
497	    }
498	    put = lsx_writebuf(ft, tmp, want * 3) / 3;
499	    done += put;
500	    if (put != want)
501	      break;
502	  }
503	  return done;
504	}
