546	/*--------------------------------- seeking ---------------------------------*/
547	
548	/* Seek to the frame containing sample `to_sample' (a count of samples over
549	 * all channels) in data that starts at `byte_offset'. */
550	int lsx_offset_seek(sox_format_t ft, off_t byte_offset, uint64_t to_sample)
551	{
552	  double wide_sample, to_bytes;
553	  off_t to;
554	
555	  if (ft->signal.channels)
556	    to_sample -= to_sample % ft->signal.channels;
557	  wide_sample = (double)to_sample;
558	  to_bytes = wide_sample * ft->encoding.bits_per_sample / 8;
559	  to = (off_t)to_bytes;
560	  if ((double)to != to_bytes)          /* overflowed */
561	    return SOX_EOF;
562	  return lsx_seeki(ft, byte_offset + to, SEEK_SET);
563	}
564	
565	/*------------------------- textual field extraction ------------------------*/
566	
567	static int rf_getc(sox_format_t ft)
568	{
569	  unsigned char b;
570	  return lsx_readbuf(ft, &b, (size_t)1) == 1 ? (int)b : -1;
571	}
572	
573	static void rf_ungetc(sox_format_t ft, int c)
574	{
575	  if (c >= 0)
576	    lsx_unreadb(ft, (unsigned)c);
577	}
578	
579	static int rf_skip_space(sox_format_t ft)
580	{
581	  int c;
582	  do
583	    c = rf_getc(ft);
584	  while (c >= 0 && isspace(c));
585	  rf_ungetc(ft, c);
586	  return c;
587	}
588	
589	static int digit_val(int c, int base)
590	{
591	  int v;
592	  if (isdigit(c)) v = c - '0';
593	  else if (isalpha(c)) v = tolower(c) - 'a' + 10;
594	  else return -1;
595	  return v < base ? v : -1;
596	}
597	
598	/* Scan whitespace-separated fields from the file according to a scanf-like
599	 * spec; see ../notes/formats_i.md for the supported conversions.  *n (if not
600	 * NULL) receives the number of fields assigned; the return value is
601	 * SOX_SUCCESS only if every directive in the spec was satisfied. */
602	int lsx_read_fields(sox_format_t ft, size_t *n, char const *spec, ...)
603	{
604	  va_list ap;
605	  size_t assigned = 0;
606	  int ok = 1;
607	
608	  va_start(ap, spec);
609	  while (*spec && ok) {
610	    if (isspace((unsigned char)*spec)) {
611	      while (isspace((unsigned char)*spec))
612	        ++spec;
613	      rf_skip_space(ft);
614	      continue;
615	    }
616	    if (*spec != '%') {
617	      int c = rf_getc(ft);
618	      if (c != (unsigned char)*spec) {
619	        rf_ungetc(ft, c);
620	        ok = 0;
621	        break;
622	      }
623	      ++spec;
624	      continue;
625	    }
626	
627	    ++spec;                                  /* past the '%' */
628	    {
629	      int suppress = 0, longs = 0, shorts = 0;
630	      size_t width = 0;
631	      int conv;
632	
633	      if (*spec == '*') { suppress = 1; ++spec; }
634	      while (isdigit((unsigned char)*spec))
635	        width = width * 10 + (size_t)(*spec++ - '0');
636	      for (;;) {
637	        if (*spec == 'l' || *spec == 'L' || *spec == 'q' || *spec == 'j' ||
638	            *spec == 'z') { ++longs; ++spec; }
639	        else if (*spec == 'h') { ++shorts; ++spec; }
640	        else break;
641	      }
642	      conv = *spec ? *spec++ : 0;
643	
644	      switch (conv) {
645	      case '%': {
646	        int c = rf_getc(ft);
647	        if (c != '%') { rf_ungetc(ft, c); ok = 0; }
648	        break;
649	      }
650	      case 'c': {
651	        size_t want = width ? width : 1, got = 0;
652	        char *p = suppress ? NULL : va_arg(ap, char *);
653	        while (got < want) {
654	          int c = rf_getc(ft);
655	          if (c < 0) break;
656	          if (p) p[got] = (char)c;
657	          ++got;
658	        }
659	        if (got != want) ok = 0;
660	        else if (p) ++assigned;
661	        break;
662	      }
663	      case 's': {
664	        char *p = suppress ? NULL : va_arg(ap, char *);
665	        size_t got = 0;
666	        int c;
667	        rf_skip_space(ft);
668	        for (;;) {
669	          c = rf_getc(ft);
670	          if (c < 0 || isspace(c)) { rf_ungetc(ft, c); break; }
671	          if (width && got >= width) { rf_ungetc(ft, c); break; }
672	          if (p) p[got] = (char)c;
673	          ++got;
674	        }
675	        if (p) p[got] = '\0';
676	        if (!got) ok = 0;
677	        else if (p) ++assigned;
678	        break;
679	      }
680	      case 'd': case 'i': case 'u': case 'x': case 'X': case 'o': {
681	        int base = conv == 'x' || conv == 'X' ? 16 : conv == 'o' ? 8 :
682	                   conv == 'i' ? 0 : 10;
683	        int neg = 0, ndig = 0, c;
684	        uint64_t v = 0;
685	        size_t used = 0;
686	
687	        rf_skip_space(ft);
688	        c = rf_getc(ft);
689	        if (c == '+' || c == '-') {
690	          neg = c == '-';
691	          ++used;
692	          c = rf_getc(ft);
693	        }
694	        if (c == '0' && (base == 16 || !base)) {  /* optional 0x / 0 prefix */
695	          int c2 = rf_getc(ft);
696	          if (c2 == 'x' || c2 == 'X') {
697	            base = 16;
698	            used += 2;
699	            c = rf_getc(ft);
700	          } else {
701	            rf_ungetc(ft, c2);
702	            if (!base)
703	              base = 8;
704	            ++ndig;                              /* the leading 0 counts */
705	            ++used;
706	            c = rf_getc(ft);
707	          }
708	        } else if (!base)
709	          base = 10;
710	        while (c >= 0 && (!width || used < width) && digit_val(c, base) >= 0) {
711	          v = v * (uint64_t)base + (uint64_t)digit_val(c, base);
712	          ++ndig; ++used;
713	          c = rf_getc(ft);
714	        }
715	        rf_ungetc(ft, c);
716	        if (!ndig) { ok = 0; break; }
717	        if (neg)
718	          v = (uint64_t)-(int64_t)v;
719	        if (!suppress) {
720	          if (longs >= 2)      *va_arg(ap, long long *) = (long long)v;
721	          else if (longs == 1) *va_arg(ap, long *) = (long)v;
722	          else if (shorts >= 2)*va_arg(ap, signed char *) = (signed char)v;
723	          else if (shorts == 1)*va_arg(ap, short *) = (short)v;
724	          else                 *va_arg(ap, int *) = (int)v;
725	          ++assigned;
726	        }
727	        break;
728	      }
729	      case 'f': case 'e': case 'E': case 'g': case 'G': {
730	        char buf[80];
731	        size_t got = 0;
732	        int c, seen_digit = 0, seen_dot = 0, seen_exp = 0;
733	        double d;
734	
735	        rf_skip_space(ft);
736	        for (;;) {
737	          c = rf_getc(ft);
738	          if (c < 0) break;
739	          if (width && got >= width) { rf_ungetc(ft, c); break; }
740	          if (got + 1 >= sizeof(buf)) { rf_ungetc(ft, c); break; }
741	          if (isdigit(c)) { seen_digit = 1; }
742	          else if ((c == '+' || c == '-') &&
743	                   (got == 0 || buf[got - 1] == 'e' || buf[got - 1] == 'E')) ;
744	          else if (c == '.' && !seen_dot && !seen_exp) seen_dot = 1;
745	          else if ((c == 'e' || c == 'E') && seen_digit && !seen_exp)
746	            seen_exp = 1;
747	          else { rf_ungetc(ft, c); break; }
748	          buf[got++] = (char)c;
749	        }
750	        buf[got] = '\0';
751	        if (!seen_digit) { ok = 0; break; }
752	        d = strtod(buf, NULL);
753	        if (!suppress) {
754	          if (longs) *va_arg(ap, double *) = d;
755	          else       *va_arg(ap, float *) = (float)d;
756	          ++assigned;
757	        }
758	        break;
759	      }
760	      default:
761	        ok = 0;
762	        break;
763	      }
764	    }
765	  }
766	  va_end(ap);
767	  if (n)
768	    *n = assigned;
769	  return ok ? SOX_SUCCESS : SOX_EOF;
770	}
