772	/*--------------------------- header vs. user options -----------------------*/
773	
774	/* Called by a format's startread once it has decoded its header.  Values that
775	 * the user has overridden on the command line win, with a warning; everything
776	 * else is taken from the header.  With --ignore-length the length implied by
777	 * the file size is used instead of the one in the header. */
778	int lsx_check_read_params(sox_format_t ft, unsigned channels, double rate,
779	                          sox_encoding_t encoding, unsigned bits_per_sample,
780	                          uint64_t num_samples, sox_bool check_length)
781	{
782	  sox_bool ignore_length = ft->ignore_length ||
783	      ft->signal.length == SOX_IGNORE_LENGTH;
784	  uint64_t calculated = 0;
785	  sox_bool have_calculated = sox_false;
786	  char const *fn = ft->filename ? ft->filename : "";
787	
788	  if (channels && ft->signal.channels && ft->signal.channels != channels)
789	    lsx_warn("`%s': overriding number of channels", fn);
790	  else ft->signal.channels = channels;
791	
792	  if (rate && ft->signal.rate && ft->signal.rate != rate)
793	    lsx_warn("`%s': overriding sample rate", fn);
794	  else ft->signal.rate = rate;
795	
796	  if (encoding && ft->encoding.encoding && ft->encoding.encoding != encoding)
797	    lsx_warn("`%s': overriding encoding type", fn);
798	  else ft->encoding.encoding = encoding;
799	
800	  if (bits_per_sample && ft->encoding.bits_per_sample &&
801	      ft->encoding.bits_per_sample != bits_per_sample)
802	    lsx_warn("`%s': overriding encoding size", fn);
803	  else ft->encoding.bits_per_sample = bits_per_sample;
804	
805	  if (!ft->signal.precision)
806	    ft->signal.precision =
807	        lsx_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);
808	
809	  if (ft->seekable && bits_per_sample) {
810	    uint64_t length = lsx_filelength(ft);
811	    off_t here = lsx_tell(ft);
812	    if (here >= 0 && length >= (uint64_t)here) {
813	      calculated = (length - (uint64_t)here) * 8 / bits_per_sample;
814	      have_calculated = sox_true;
815	    }
816	  }
817	
818	  if (ignore_length)
819	    ft->signal.length = have_calculated ? calculated : SOX_UNSPEC;
820	  else {
821	    if (num_samples && num_samples != SOX_UNKNOWN_LEN)
822	      ft->signal.length = num_samples;
823	    if (check_length && have_calculated &&
824	        num_samples && num_samples != SOX_UNKNOWN_LEN &&
825	        num_samples != calculated)
826	      lsx_warn("`%s': file header gives the total number of samples as %llu "
827	               "but file length indicates the number is in fact %llu",
828	               fn, (unsigned long long)num_samples,
829	               (unsigned long long)calculated);
830	  }
831	  return SOX_SUCCESS;
832	}
