285	
286	int lsx_rawstartread(sox_format_t ft)
287	{
288	  off_t here = lsx_tell(ft);
289	
290	  ft->data_start = here > 0 ? (uint64_t)here : 0;
291	
292	  if (ft->mode == 'r' && ft->signal.length == SOX_UNSPEC &&
293	      !ft->ignore_length && ft->encoding.bits_per_sample) {
294	    uint64_t bytes = lsx_filelength(ft);
295	    if (bytes > ft->data_start)
296	      ft->signal.length =
297	          (bytes - ft->data_start) * 8 / ft->encoding.bits_per_sample;
298	  }
299	  return SOX_SUCCESS;
300	}
301	
302	int lsx_rawstartwrite(sox_format_t ft)
303	{
304	  off_t here = lsx_tell(ft);
305	
306	  ft->data_start = here > 0 ? (uint64_t)here : 0;
307	  return SOX_SUCCESS;
308	}
